using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------

var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------

var researchTools = new ResearchTools();

var tools = new List<AIFunction>
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// ---------------------------------------------------------------------------
// Chat client with automatic function invocation
// ---------------------------------------------------------------------------

IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------

Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    researchTools.ClearNotes();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, """
            You are a research agent. When the user gives you a topic:
            1. Use the SearchWeb tool multiple times with different queries to gather information.
            2. Use the SaveNote tool to record key findings as you go.
            3. After gathering enough information, use GetNotes to review everything you saved.
            4. Finally, provide a well-structured summary of your research to the user.
            Be thorough: search at least 2-3 different queries per topic.
            """),
        new(ChatRole.User, $"Research the following topic: {topic}"),
    };

    Console.WriteLine($"\nResearching \"{topic}\"...\n");

    var response = await client.GetResponseAsync(messages, chatOptions);

    Console.WriteLine("--- Research Summary ---\n");
    Console.WriteLine(response.Text);
    Console.WriteLine("\n------------------------");
}

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------

/// <summary>Tools available to the research agent.</summary>
sealed class ResearchTools
{
    private static readonly HttpClient Http = new();
    private readonly List<string> _notes = [];

    [Description("Search the web for information on a query. Returns a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Abstract / main result
            var abstractText = json.GetProperty("AbstractText").GetString();
            var abstractSource = json.GetProperty("AbstractSource").GetString();
            var abstractUrl = json.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
                results.Add($"[{abstractSource}] {abstractText}\nURL: {abstractUrl}");

            // Related topics
            if (json.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var link = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                    if (!string.IsNullOrWhiteSpace(text))
                        results.Add($"• {text}\n  URL: {link}");
                }
            }

            if (results.Count == 0)
                return $"No results found for \"{query}\". Try a different search query.";

            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📋 Retrieving {_notes.Count} note(s)");
        return string.Join("\n---\n",
            _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }

    public void ClearNotes() => _notes.Clear();
}

